import { createHash } from "node:crypto";
import { GoogleAuth } from "google-auth-library";

/**
 * Static apps served through the gate.
 *
 * A static app is a built site kept in a private Cloud Storage bucket. The
 * gate verifies the session and the member's per-app grant, then reads the
 * object server-side with the runtime service account. The bucket has public
 * access prevention enforced and no signed URLs are issued, so these routes
 * are the only way to the bytes.
 *
 * The gate's Next.js basePath is /lsv/dailysummary. Each app's public path
 * sits outside it and reaches the route in src/app/apps/[app] through a
 * loopback rewrite declared in next.config.ts.
 */
export type StaticApp = {
  slug: string;
  title: string;
  /** Public URL path, outside the Next.js basePath. */
  publicPath: string;
};

export const STATIC_APPS: Record<string, StaticApp> = {
  "limsoc-permission-assist": {
    slug: "limsoc-permission-assist",
    title: "LIMSOC Permission Assist",
    publicPath: "/lsv/limsoc-permission-assist",
  },
};

/** Bucket naming follows the project: <project>-<app slug>. */
export function bucketFor(app: StaticApp): string {
  const override = process.env[`STATIC_APP_BUCKET_${app.slug.toUpperCase().replace(/-/g, "_")}`];
  if (override) return override;
  const project = process.env.GOOGLE_CLOUD_PROJECT ?? process.env.FIREBASE_PROJECT_ID ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
  if (!project) throw new Error("No project id available to derive the static app bucket name");
  return `${project}-${app.slug}`;
}

const CONTENT_TYPES: Record<string, string> = {
  html: "text/html; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
  json: "application/json; charset=utf-8",
  svg: "image/svg+xml",
  png: "image/png",
  ico: "image/x-icon",
  woff2: "font/woff2",
  txt: "text/plain; charset=utf-8",
};

export function contentTypeFor(objectName: string): string | null {
  const ext = objectName.includes(".") ? objectName.split(".").pop()!.toLowerCase() : "";
  return CONTENT_TYPES[ext] ?? null;
}

/**
 * Map URL path segments to an object name, or null when the path is not one
 * this server will read. Segments are plain names only: no dot-segments, no
 * hidden files, no encoded separators, and only known file types.
 */
export function resolveObject(segments: string[] | undefined): string | null {
  const parts = (segments ?? []).filter((s) => s !== "");
  if (parts.length === 0) return "index.html";
  if (parts.length > 6) return null;
  for (const p of parts) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,100}$/.test(p)) return null;
    if (p.includes("..")) return null;
  }
  const name = parts.join("/");
  return contentTypeFor(name) ? name : null;
}

/**
 * sha256 sources for every inline script that the browser would execute.
 * Data blocks (type="application/json") are never executed and need none.
 * The HTML parser normalises newlines before a script is hashed, so the
 * same normalisation is applied here.
 */
export function inlineScriptHashes(html: string): string[] {
  const out: string[] = [];
  const re = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    const attrs = m[1];
    if (/\bsrc\s*=/i.test(attrs)) continue;
    const type = /\btype\s*=\s*["']?([^"'\s>]+)/i.exec(attrs)?.[1]?.toLowerCase();
    if (type && type !== "text/javascript" && type !== "module") continue;
    const text = m[2].replace(/\r\n?/g, "\n");
    out.push(`'sha256-${createHash("sha256").update(text, "utf8").digest("base64")}'`);
  }
  return out;
}

/**
 * Same-origin scripts plus the page's own inline script, and no network
 * access at all: the page works entirely on files the member picks, so
 * connect-src 'none' makes "never calls another system" a browser-enforced
 * property. Inline style attributes are allowed because the page writes them.
 */
export function buildCsp(scriptHashes: string[]): string {
  return [
    "default-src 'none'",
    `script-src ${["'self'", ...scriptHashes].join(" ")}`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "font-src 'self' data:",
    "connect-src 'none'",
    "frame-src 'none'",
    "worker-src 'none'",
    "manifest-src 'none'",
    "object-src 'none'",
    "base-uri 'none'",
    "form-action 'none'",
    "frame-ancestors 'none'",
  ].join("; ");
}

/** Headers on every response under a static app, whatever the status. */
export const STATIC_APP_HEADERS: Record<string, string> = {
  "X-Robots-Tag": "noindex, nofollow",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Resource-Policy": "same-origin",
};

export type StoredObject = { body: Buffer; generation: string };

let _auth: GoogleAuth | null = null;
const cache = new Map<string, StoredObject>();

/**
 * Read an object with the runtime service account. The last copy is kept in
 * memory and revalidated against its generation on every request, so a new
 * upload or a rollback is live on the next request and an unchanged object
 * costs one conditional GET with no body.
 */
export async function fetchObject(bucket: string, objectName: string): Promise<StoredObject | null> {
  _auth ??= new GoogleAuth({ scopes: ["https://www.googleapis.com/auth/devstorage.read_only"] });
  const token = await _auth.getAccessToken();
  const key = `${bucket}/${objectName}`;
  const cached = cache.get(key);
  const url = new URL(`https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(bucket)}/o/${encodeURIComponent(objectName)}`);
  url.searchParams.set("alt", "media");
  if (cached) url.searchParams.set("ifGenerationNotMatch", cached.generation);
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
  if (res.status === 304 && cached) return cached;
  if (res.status === 404) {
    cache.delete(key);
    return null;
  }
  if (!res.ok) throw new Error(`Storage read failed for ${key}: ${res.status}`);
  const stored: StoredObject = { body: Buffer.from(await res.arrayBuffer()), generation: res.headers.get("x-goog-generation") ?? "" };
  if (stored.generation) cache.set(key, stored);
  return stored;
}

/** A member may open a static app only with an explicit grant for it. */
export function hasAppGrant(user: { apps?: string[] } | null | undefined, slug: string): boolean {
  return !!user && Array.isArray(user.apps) && user.apps.includes(slug);
}
EOF
