import { NextRequest, NextResponse } from "next/server";
import { getAuthUser } from "@/lib/auth";
import { clientEnv } from "@/env";
import {
  STATIC_APPS,
  STATIC_APP_HEADERS,
  bucketFor,
  buildCsp,
  contentTypeFor,
  fetchObject,
  hasAppGrant,
  inlineScriptHashes,
  resolveObject,
} from "@/lib/static-app";

export const dynamic = "force-dynamic";

/**
 * Serves a static app from its private bucket to signed-in members who hold
 * the app's grant. See src/lib/static-app.ts.
 *
 * Order matters: session first, then grant, and only then is the path looked
 * at or the bucket read. A signed-out request to any path under the app,
 * existing or not, gets the sign-in redirect and nothing else.
 */
function respond(body: BodyInit | null, status: number, headers: Record<string, string> = {}) {
  return new NextResponse(body, { status, headers: { ...STATIC_APP_HEADERS, "Cache-Control": "private, no-store", ...headers } });
}

function message(status: number, title: string, text: string) {
  const html = `<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body><h1>${title}</h1><p>${text}</p></body></html>`;
  return respond(html, status, { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'" });
}

export async function GET(request: NextRequest, ctx: { params: Promise<{ app: string; path?: string[] }> }) {
  const { app: slug, path } = await ctx.params;
  const app = STATIC_APPS[slug];
  const base = clientEnv.NEXT_PUBLIC_BASE_PATH;

  const user = await getAuthUser();
  if (!user) {
    // Relative on purpose: through the loopback rewrite this handler does not see the public host.
    const back = app ? `/apps/${app.slug}` : "/";
    return respond(null, 303, { Location: `${base}/sign-in?redirect=${encodeURIComponent(back)}` });
  }
  if (!app) return message(404, "Not found", "There is nothing at this address.");
  if (!hasAppGrant(user, app.slug)) {
    return message(403, "No access", `You are signed in as ${user.email}, but you do not have access to ${app.title}. Ask the administrator to add you.`);
  }

  // Requests arriving on the inner path directly (for example straight after sign-in) move to the public address.
  const viaLoopback = /^(127\.0\.0\.1|localhost)(:\d+)?$/.test(request.headers.get("host") ?? "");
  if (!viaLoopback) {
    const rest = (path ?? []).map(encodeURIComponent).join("/");
    return respond(null, 308, { Location: rest ? `${app.publicPath}/${rest}` : app.publicPath });
  }

  const objectName = resolveObject(path);
  if (!objectName) return message(404, "Not found", "There is nothing at this address.");

  let stored;
  try {
    stored = await fetchObject(bucketFor(app), objectName);
  } catch (err) {
    console.error("Static app read failed:", err);
    return message(502, "Temporarily unavailable", "The page could not be loaded. Try again shortly.");
  }
  if (!stored) return message(404, "Not found", "There is nothing at this address.");

  const contentType = contentTypeFor(objectName)!;
  if (objectName.endsWith(".html")) {
    const html = stored.body.toString("utf8");
    return respond(html, 200, {
      "Content-Type": contentType,
      "Content-Security-Policy": buildCsp(inlineScriptHashes(html)),
      "X-Static-App-Generation": stored.generation,
    });
  }

  const etag = `"${stored.generation}"`;
  const assetHeaders = { "Content-Type": contentType, "Cache-Control": "private, no-cache", ETag: etag };
  if (request.headers.get("if-none-match") === etag) return respond(null, 304, assetHeaders);
  return respond(new Uint8Array(stored.body), 200, assetHeaders);
}
