# LIMSOC Permission Assist — a static app served through the gate.
#
# The built site lives in a private bucket. The gate's runtime service account
# reads it server-side for signed-in members who hold the app grant
# (src/lib/static-app.ts); nothing else can read it. The app's own repository
# publishes to the bucket from GitHub Actions through its own WIF provider and
# a deploy account that can write objects in this bucket and do nothing else.
#
# Everything here is additive: no resource in main.tf is changed.

locals {
  permission_assist_slug = "limsoc-permission-assist"
}

variable "permission_assist_repository" {
  description = "owner/name of the GitHub repo allowed to publish the LIMSOC Permission Assist site"
  type        = string
  default     = "nicholas-wood/limsoc-permission-assist"
}

resource "google_project_service" "storage" {
  service            = "storage.googleapis.com"
  disable_on_destroy = false
}

# Standard class, single region: the cheapest fit for a small file that is
# read often (colder classes charge per read and have minimum durations).
resource "google_storage_bucket" "permission_assist" {
  name                        = "${var.project_id}-${local.permission_assist_slug}"
  location                    = upper(var.region)
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
  force_destroy               = false

  # Every upload keeps the previous build, so rollback is one command.
  versioning {
    enabled = true
  }

  # Keep the ten most recent superseded builds of each object; drop older ones.
  lifecycle_rule {
    condition {
      with_state         = "ARCHIVED"
      num_newer_versions = 10
    }
    action {
      type = "Delete"
    }
  }

  depends_on = [google_project_service.storage]
}

# The gate reads objects in this bucket only. No project-level storage role.
resource "google_storage_bucket_iam_member" "permission_assist_run_viewer" {
  bucket = google_storage_bucket.permission_assist.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.run.email}"
}

# ── Publishing from the app's repository ─────────────────────────────────────
resource "google_service_account" "permission_assist_deploy" {
  account_id   = "limsoc-pa-deploy"
  display_name = "LIMSOC Permission Assist GitHub deploy"
}

# objectUser: create, overwrite, read and list objects (and their versions) in
# this bucket. It cannot change the bucket or its IAM policy.
resource "google_storage_bucket_iam_member" "permission_assist_deploy_writer" {
  bucket = google_storage_bucket.permission_assist.name
  role   = "roles/storage.objectUser"
  member = "serviceAccount:${google_service_account.permission_assist_deploy.email}"
}

# A provider of its own in the existing pool, so the condition names one
# repository and one branch and the gate's own provider is left untouched.
resource "google_iam_workload_identity_pool_provider" "permission_assist" {
  workload_identity_pool_id          = google_iam_workload_identity_pool.github.workload_identity_pool_id
  workload_identity_pool_provider_id = local.permission_assist_slug
  display_name                       = "LIMSOC Permission Assist"
  attribute_mapping = {
    "google.subject"       = "assertion.sub"
    "attribute.repository" = "assertion.repository"
    "attribute.ref"        = "assertion.ref"
  }
  attribute_condition = "assertion.repository == \"${var.permission_assist_repository}\" && assertion.ref == \"refs/heads/main\""
  oidc {
    issuer_uri = "https://token.actions.githubusercontent.com"
  }
}

resource "google_service_account_iam_member" "permission_assist_deploy_wif" {
  service_account_id = google_service_account.permission_assist_deploy.name
  role               = "roles/iam.workloadIdentityUser"
  member             = "principalSet://iam.googleapis.com/${google_iam_workload_identity_pool.github.name}/attribute.repository/${var.permission_assist_repository}"
}

