#!/usr/bin/env bun
/**
 * Who may open a static app served through the gate (see src/lib/static-app.ts).
 *
 *   bun run scripts/app-access.ts list   <app>
 *   bun run scripts/app-access.ts grant  <app> <email> ["Display Name"]
 *   bun run scripts/app-access.ts revoke <app> <email>
 *
 * A grant is the app's slug in the member's `apps` list on the allow-list
