import { initializeApp, applicationDefault } from "firebase-admin/app";
import { FieldValue, getFirestore } from "firebase-admin/firestore";

const KNOWN_APPS = ["limsoc-permission-assist"];

const args = process.argv.slice(2);
const pi = args.indexOf("--project");
const projectId = (pi >= 0 ? args.splice(pi, 2)[1] : undefined) ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? process.env.GOOGLE_CLOUD_PROJECT ?? "lsv-oss-prod";
const [verb, app, emailArg, displayName] = args;

function usage(): never {
  console.error('usage: bun run scripts/app-access.ts list|grant|revoke <app> [email] ["Display Name"] [--project id]');
  process.exit(2);
}
if (!verb || !app || !["list", "grant", "revoke"].includes(verb)) usage();
if (!KNOWN_APPS.includes(app)) {
  console.error(`Unknown app "${app}". Known: ${KNOWN_APPS.join(", ")}`);
  process.exit(2);
}

initializeApp({ credential: applicationDefault(), projectId });
const members = getFirestore().collection("members");

if (verb === "list") {
  const snap = await members.where("apps", "array-contains", app).get();
  if (snap.empty) console.log(`No one has access to ${app}.`);
  for (const d of snap.docs) console.log(`${d.get("email")}\t${d.get("displayName")}\t${d.get("role")}`);
  process.exit(0);
}

const email = (emailArg ?? "").toLowerCase().trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) usage();
const ref = members.doc(email);
const snap = await ref.get();

if (verb === "grant") {
  if (!snap.exists) {
    if (!displayName) {
      console.error(`${email} is not on the allow-list yet. Give a display name to add them: grant ${app} ${email} "First Last"`);
      process.exit(2);
    }
    await ref.set({ email, displayName: displayName.trim(), role: "member", apps: [app], addedBy: "app-access script", addedAt: new Date().toISOString() });
    console.log(`member added: ${email} (${displayName.trim()}), granted ${app}`);
  } else {
    await ref.update({ apps: FieldValue.arrayUnion(app) });
    console.log(`granted ${app} to ${email}`);
  }
} else {
  if (!snap.exists) {
    console.log(`${email} is not on the allow-list; nothing to revoke.`);
  } else {
    await ref.update({ apps: FieldValue.arrayRemove(app) });
    console.log(`revoked ${app} from ${email}`);
  }
}
