import { NextResponse, type NextRequest } from "next/server";

/**
 * Edge gate: anything that is not an auth surface needs a session cookie to
 * exist. The cookie is verified properly in getAuthUser(); this just stops
 * anonymous requests from reaching the site handler at all, including the
 * vendored script that only the signed-in page loads.
 */
const PUBLIC_PREFIXES = ["/sign-in", "/auth/", "/not-a-member", "/logout", "/api/auth/", "/api/health", "/_next/"];

export function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname;
  if (PUBLIC_PREFIXES.some((p) => path === p.replace(/\/$/, "") || path.startsWith(p.endsWith("/") ? p : `${p}/`) || path === p)) {
    return NextResponse.next();
  }
  if (request.cookies.get("__session")?.value) return NextResponse.next();
  if (path.startsWith("/api/")) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401, headers: { "Cache-Control": "private, no-store" } });
  }
  // Built from the configured origin, not the request host: behind Firebase
  // Hosting the request arrives with the Cloud Run hostname.
  const origin = process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin;
  const res = NextResponse.redirect(`${origin}/sign-in`, { status: 303 });
  res.headers.set("Cache-Control", "private, no-store");
  return res;
}

export const config = {
