#!/usr/bin/env bun
/**
 * The member allow-list: who may sign in to LIMSOC Permission Assist.
 *
 *   bun run members list
 *   bun run members add    <email> "Display Name" [--admin]
 *   bun run members remove <email>
 *
 * One doc per member in Firestore `members/<lower-cased email>`. Only listed
 * emails can hold a session. Adding takes effect at the person's next
 * sign-in; removing takes effect on their next request and revokes their
 * Firebase sessions. Nothing is redeployed.
 *
 * Auth: gcloud ADC (`gcloud auth application-default login`) with access to
 * the project named by --project, NEXT_PUBLIC_FIREBASE_PROJECT_ID or
 * GOOGLE_CLOUD_PROJECT. Default project: limsoc-pa-prod.
 */
import { initializeApp, applicationDefault } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { getFirestore } from "firebase-admin/firestore";

const args = process.argv.slice(2);
const pi = args.indexOf("--project");
const projectId = (pi >= 0 ? args.splice(pi, 2)[1] : undefined) ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? process.env.GOOGLE_CLOUD_PROJECT ?? "limsoc-pa-prod";
const ai = args.indexOf("--admin");
const admin = ai >= 0;
if (admin) args.splice(ai, 1);
const [verb, emailArg, displayName] = args;

function usage(): never {
  console.error('usage: bun run members list | add <email> "Display Name" [--admin] | remove <email>   [--project id]');
  process.exit(2);
}
if (!verb || !["list", "add", "remove"].includes(verb)) usage();

initializeApp({ credential: applicationDefault(), projectId });
const members = getFirestore().collection("members");

if (verb === "list") {
  const snap = await members.orderBy("displayName").get();
  if (snap.empty) console.log("No members.");
  for (const d of snap.docs) console.log(`${d.get("email")}\t${d.get("displayName")}\t${d.get("role")}`);
  process.exit(0);
}

const email = (emailArg ?? "").toLowerCase().trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) usage();
const ref = members.doc(email);
const snap = await ref.get();

if (verb === "add") {
  if (!displayName) usage();
  const role = admin ? "admin" : "member";
  if (snap.exists) {
    await ref.set({ displayName: displayName.trim(), role }, { merge: true });
    console.log(`member updated: ${email} (${displayName.trim()}, ${role})`);
  } else {
    await ref.set({ email, displayName: displayName.trim(), role, addedBy: "members script", addedAt: new Date().toISOString() });
    console.log(`member added: ${email} (${displayName.trim()}, ${role})`);
  }
} else {
  if (!snap.exists) {
    console.log(`${email} is not a member; nothing to remove.`);
  } else {
    const uid = snap.get("uid") as string | undefined;
    await ref.delete();
    if (uid) {
      await getAuth().setCustomUserClaims(uid, { member: false, admin: false });
      await getAuth().revokeRefreshTokens(uid);
    }
    console.log(`member removed: ${email}`);
  }
}
