import { describe, expect, test } from "bun:test";
import { createHash } from "node:crypto";
import { buildCsp, contentTypeFor, inlineScriptHashes, resolveObject, siteBucket } from "../src/lib/site";

describe("resolveObject", () => {
  test("root is the page", () => {
    expect(resolveObject(undefined)).toBe("index.html");
    expect(resolveObject([])).toBe("index.html");
  });
  test("plain nested files of known types", () => {
    expect(resolveObject(["vendor", "xlsx.full.min.js"])).toBe("vendor/xlsx.full.min.js");
  });
  test("refuses traversal, hidden files, encoded separators and unknown types", () => {
    for (const bad of [[".."], ["..", "index.html"], ["vendor", "..", "x.js"], ["a..b.js"], [".env"], ["..%2f..%2fapi", "health"], ["a/b.js"], ["a\\b.js"], ["x.exe"], ["noext"], ["a b.js"], ["%2e%2e", "x.js"]]) {
      expect(resolveObject(bad)).toBeNull();
    }
  });
  test("refuses very deep paths", () => {
    expect(resolveObject(["a", "b", "c", "d", "e", "f", "g.js"])).toBeNull();
  });
});

describe("inlineScriptHashes", () => {
  const app = "\nvar a=1;\n";
  test("hashes executable inline scripts only", () => {
    const html = `<script type="application/json" id="seed">{"x":1}</script><script src="/vendor/x.js"></script><script>${app}</script>`;
    expect(inlineScriptHashes(html)).toEqual([`'sha256-${createHash("sha256").update(app).digest("base64")}'`]);
    expect(inlineScriptHashes(`<script type="application/json">{"a":1}</script><script src="x.js"></script>`)).toEqual([]);
  });
  test("normalises newlines the way the HTML parser does", () => {
    expect(inlineScriptHashes("<script>a\r\nb</script>")).toEqual(inlineScriptHashes("<script>a\nb</script>"));
  });
});

describe("buildCsp", () => {
  const csp = buildCsp(["'sha256-abc'"]);
  test("scripts are same-origin plus the given hashes", () => {
    expect(csp).toContain("script-src 'self' 'sha256-abc'");
    expect(csp.split(";").find((d) => d.trim().startsWith("script-src"))).not.toMatch(/unsafe-inline|unsafe-eval|https?:|\*/);
  });
  test("no network, framing, plugins, base or form targets", () => {
    for (const d of ["default-src 'none'", "connect-src 'none'", "object-src 'none'", "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'"]) {
      expect(csp).toContain(d);
    }
  });
});

describe("configuration", () => {
  test("the bucket must be configured", () => {
    delete process.env.SITE_BUCKET;
    expect(() => siteBucket()).toThrow();
    process.env.SITE_BUCKET = "limsoc-pa-prod-site";
    expect(siteBucket()).toBe("limsoc-pa-prod-site");
  });
  test("content types", () => {
    expect(contentTypeFor("index.html")).toBe("text/html; charset=utf-8");
    expect(contentTypeFor("vendor/xlsx.full.min.js")).toBe("text/javascript; charset=utf-8");
    expect(contentTypeFor("x.php")).toBeNull();
  });
});
