  delete_protection_state           = "DELETE_PROTECTION_ENABLED"
  deletion_policy                   = "ABANDON"
  point_in_time_recovery_enablement = "POINT_IN_TIME_RECOVERY_DISABLED"
  depends_on                        = [google_project_service.apis]
}

resource "google_firebaserules_ruleset" "firestore" {
  provider = google-beta
  source {
    files {
      name    = "firestore.rules"
      content = file("${path.module}/../../host/firestore.rules")
    }
  }
  depends_on = [google_firestore_database.default, google_firebase_project.default]
}

resource "google_firebaserules_release" "firestore" {
  provider     = google-beta
  name         = "cloud.firestore"
  ruleset_name = google_firebaserules_ruleset.firestore.name
  lifecycle {
    replace_triggered_by = [google_firebaserules_ruleset.firestore]
  }
}

# ── The site: a private bucket ───────────────────────────────────────────────
# Standard class, single region: the cheapest fit for a small file that is
# read often (colder classes charge per read and have minimum durations).
resource "google_storage_bucket" "site" {
  name                        = "${var.project_id}-site"
  location                    = upper(var.region)
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
  force_destroy               = false

  # Every upload keeps the previous build, so rollback is one command.
  versioning {
    enabled = true
  }

  # Keep the ten most recent superseded builds of each object; drop older ones.
  lifecycle_rule {
    condition {
      with_state         = "ARCHIVED"
      num_newer_versions = 10
    }
    action {
      type = "Delete"
    }
  }

  depends_on = [google_project_service.apis]
}

# The only reader: the Cloud Run runtime account, on this bucket only.
resource "google_storage_bucket_iam_member" "site_run_viewer" {
  bucket = google_storage_bucket.site.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.run.email}"
}

# The only writer: the GitHub deploy account, objects in this bucket only.
resource "google_storage_bucket_iam_member" "site_deploy_writer" {
  bucket = google_storage_bucket.site.name
  role   = "roles/storage.objectUser"
  member = "serviceAccount:${google_service_account.deploy.email}"
}

# ── Artifact Registry ────────────────────────────────────────────────────────
resource "google_artifact_registry_repository" "app" {
  location      = var.region
  repository_id = "limsoc-pa"
  format        = "DOCKER"
  # Keep the three newest images (current, previous for rollback, one spare) and nothing else.
  cleanup_policies {
    id     = "keep-recent"
    action = "KEEP"
    most_recent_versions {
      keep_count = 3
    }
  }
  cleanup_policies {
    id     = "delete-older"
    action = "DELETE"
    condition {
      older_than = "86400s"
    }
  }
  depends_on = [google_project_service.apis]
}

# ── Secrets ──────────────────────────────────────────────────────────────────
resource "random_password" "session_signing_secret" {
  length  = 64
  special = false
}

resource "google_secret_manager_secret" "session_signing_secret" {
  secret_id = "session-signing-secret"
  replication {
    auto {}
  }
  depends_on = [google_project_service.apis]
}

resource "google_secret_manager_secret_version" "session_signing_secret" {
  secret      = google_secret_manager_secret.session_signing_secret.id
  secret_data = random_password.session_signing_secret.result
}

# ── Service accounts ─────────────────────────────────────────────────────────
resource "google_service_account" "run" {
  account_id   = "limsoc-pa-run"
  display_name = "LIMSOC Permission Assist Cloud Run runtime"
  depends_on   = [google_project_service.apis]
}

resource "google_project_iam_member" "run_roles" {
  for_each = toset([
    "roles/datastore.user",
    "roles/firebaseauth.admin",
    "roles/logging.logWriter",
  ])
  project = var.project_id
  role    = each.key
  member  = "serviceAccount:${google_service_account.run.email}"
}

# Firebase Admin on ADC signs session cookies via IAM signBlob.
resource "google_service_account_iam_member" "run_self_token_creator" {
  service_account_id = google_service_account.run.name
  role               = "roles/iam.serviceAccountTokenCreator"
  member             = "serviceAccount:${google_service_account.run.email}"
}

resource "google_secret_manager_secret_iam_member" "run_session_secret" {
  secret_id = google_secret_manager_secret.session_signing_secret.secret_id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.run.email}"
}

# ── Cloud Run ────────────────────────────────────────────────────────────────
resource "google_cloud_run_v2_service" "app" {
  name                = local.service_name
  location            = var.region
  ingress             = "INGRESS_TRAFFIC_ALL"
  deletion_protection = var.environment == "prod"

  template {
    service_account                  = google_service_account.run.email
    max_instance_request_concurrency = 80
    timeout                          = "60s"
    scaling {
      min_instance_count = 0
      max_instance_count = 2
    }
    containers {
      image = var.initial_image
      ports {
        container_port = 3000
      }
      resources {
        limits            = { cpu = "1", memory = "512Mi" }
        cpu_idle          = true
        startup_cpu_boost = true
      }
      startup_probe {
        http_get {
          path = "/api/health"
          port = 3000
        }
        initial_delay_seconds = 2
        period_seconds        = 3
        failure_threshold     = 10
      }
      env {
        name  = "NEXT_PUBLIC_APP_URL"
        value = local.app_url
      }
      env {
        name  = "NEXT_PUBLIC_FIREBASE_PROJECT_ID"
        value = var.project_id
      }
      env {
        name  = "SITE_BUCKET"
        value = google_storage_bucket.site.name
      }
      env {
        name = "SESSION_SIGNING_SECRET"
        value_source {
          secret_key_ref {
            secret  = google_secret_manager_secret.session_signing_secret.secret_id
            version = "latest"
          }
        }
      }
    }
  }

  lifecycle {
    # CI sets the image on each release; Terraform owns everything else.
    ignore_changes = [template[0].containers[0].image, client, client_version, template[0].labels, scaling]
  }
  depends_on = [
    google_project_service.apis,
    google_secret_manager_secret_version.session_signing_secret,
    google_secret_manager_secret_iam_member.run_session_secret,
  ]
}

# Public invoker: the app enforces its own sign-in, exactly like AccessBuddy,
# and Firebase Hosting needs to reach it.
resource "google_cloud_run_v2_service_iam_member" "public" {
  name     = google_cloud_run_v2_service.app.name
  location = var.region
  role     = "roles/run.invoker"
  member   = "allUsers"
}

# ── Firebase Hosting: the front door ─────────────────────────────────────────
# Cloud Run domain mappings are not available in australia-southeast1, so the
# hostname terminates at Firebase Hosting (free tier, Google-managed TLS) and
# every path is rewritten to the Cloud Run service. Hosting forwards only the
# `__session` cookie, which is why the app uses that name. Hosting holds no
# files of its own: nothing is served without passing the service's sign-in.
resource "google_firebase_hosting_site" "default" {
  provider   = google-beta
  project    = var.project_id
  site_id    = var.project_id
  depends_on = [google_firebase_project.default]
}

resource "google_firebase_hosting_version" "front" {
  provider = google-beta
  site_id  = google_firebase_hosting_site.default.site_id
  config {
    rewrites {
      glob = "**"
      run {
        service_id = google_cloud_run_v2_service.app.name
        region     = var.region
      }
    }
  }
}

resource "google_firebase_hosting_release" "front" {
  provider     = google-beta
  site_id      = google_firebase_hosting_site.default.site_id
  version_name = google_firebase_hosting_version.front.name
  message      = "Rewrite everything to Cloud Run"
}

resource "google_firebase_hosting_custom_domain" "app" {
  count                 = var.domain == "" ? 0 : 1
  provider              = google-beta
  project               = var.project_id
  site_id               = google_firebase_hosting_site.default.site_id
  custom_domain         = var.domain
  wait_dns_verification = false
}

# ── Workload Identity Federation for GitHub Actions ──────────────────────────
resource "google_iam_workload_identity_pool" "github" {
  workload_identity_pool_id = "github"
  display_name              = "GitHub Actions"
  depends_on                = [google_project_service.apis]
}

# Pinned to the repository and owner by GitHub's numeric ids (they survive
# renames and cannot be claimed by re-registering an old name) and to main.
# Pull requests and other branches cannot obtain a token.
resource "google_iam_workload_identity_pool_provider" "github" {
  workload_identity_pool_id          = google_iam_workload_identity_pool.github.workload_identity_pool_id
  workload_identity_pool_provider_id = "github-oidc"
  display_name                       = "GitHub OIDC"
  attribute_mapping = {
    "google.subject"          = "assertion.sub"
    "attribute.repository"    = "assertion.repository"
    "attribute.repository_id" = "assertion.repository_id"
    "attribute.ref"           = "assertion.ref"
  }
  attribute_condition = "assertion.repository_id == \"${var.github_repository_id}\" && assertion.repository_owner_id == \"${var.github_repository_owner_id}\" && assertion.ref == \"refs/heads/main\""
  oidc {
    issuer_uri = "https://token.actions.githubusercontent.com"
  }
}

resource "google_service_account" "deploy" {
  account_id   = "limsoc-pa-deploy"
  display_name = "LIMSOC Permission Assist GitHub deploy"
  depends_on   = [google_project_service.apis]
}

resource "google_service_account_iam_member" "deploy_wif" {
  service_account_id = google_service_account.deploy.name
  role               = "roles/iam.workloadIdentityUser"
  member             = "principalSet://iam.googleapis.com/${google_iam_workload_identity_pool.github.name}/attribute.repository_id/${var.github_repository_id}"
}

resource "google_project_iam_member" "deploy_roles" {
  for_each = toset(["roles/run.developer", "roles/artifactregistry.writer"])
  project  = var.project_id
  role     = each.key
  member   = "serviceAccount:${google_service_account.deploy.email}"
}

resource "google_service_account_iam_member" "deploy_acts_as_run" {
  service_account_id = google_service_account.run.name
  role               = "roles/iam.serviceAccountUser"
  member             = "serviceAccount:${google_service_account.deploy.email}"
}
